mapper.select:
SELECT t.id, t.service_name AS serviceName, et.id AS termId, et.term_name AS termName, et.start_date AS startDate, et.end_date AS endDate FROM t_as_service t left join t_educl_term et on t.term_id = et.id where t.is_valid = 1 and et.is_valid = 1
and t.school_id = #{query.schoolId}
and t.service_name like CONCAT('%', #{query.serviceName}, '%')
and t.term_id = #{query.termId}
and et.term_name like CONCAT('%', #{query.termName}, '%')
order by t.create_time desc

SELECT DISTINCT cc.*
FROM t_as_service s
INNER JOIN t_as_course_class cc ON cc.service_id = s.id AND cc.is_valid = 1
WHERE s.is_valid = 1
  AND s.school_id = #{schoolId}

    and s.term_id = #{termId}
